package com.mockarena.evaluation.api;
import com.mockarena.evaluation.application.CodingEvaluationJobService; import com.mockarena.evaluation.domain.CodingEvaluationJob; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/internal/v1/coding-evaluation-jobs") public class CodingEvaluationJobController { private final CodingEvaluationJobService jobs; public CodingEvaluationJobController(CodingEvaluationJobService jobs){this.jobs=jobs;} @PostMapping public Response accept(@Valid @RequestBody Request r){CodingEvaluationJob j=jobs.accept(r.attemptId(),r.globalPosition(),r.questionId(),r.questionVersionId(),r.submittedResponseFingerprint(),r.programmingLanguage());return new Response(j.jobId(),j.status().name());} public record Request(@NotNull UUID attemptId,@Positive int globalPosition,@NotNull UUID questionId,@NotNull UUID questionVersionId,@Size(max=64) String submittedResponseFingerprint,@Size(max=64) String programmingLanguage){} public record Response(UUID jobId,String status){} }
